package com.srenterprises.controller; import com.srenterprises.dto.OrderDtos.*; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import com.srenterprises.service.*; import jakarta.validation.*; import org.springframework.data.domain.*; import org.springframework.security.access.prepost.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/orders") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','STAFF')") public class AdminOrderController { final OrderRepository orders; final OrderService service; AdminOrderController(OrderRepository o,OrderService s){orders=o;service=s;} @GetMapping public Page<CustomerOrder> all(@RequestParam(defaultValue="0") int page){return orders.findAll(PageRequest.of(page,25,Sort.by("createdAt").descending()));} @PutMapping("/{id}/status") public CustomerOrder status(@PathVariable UUID id,@Valid @RequestBody Status s){return service.status(id,s.status());} }
